out=s; used=0
for k,v in TR.items():
    pat=re.compile(r"(?<=[\">'])"+re.escape(k)+r"(?=[\"<'])")
    out,c=pat.subn(lambda m:v,out)
    if c: used+=1
    else: print("UNUSED",k[:70])
for o,n in RAW:
    if o not in out: print("RAWMISS",o[:60]); continue
    out=out.replace(o,n)
out,c=re.subn(r'(<meta name="app-version" content="2026-11-24)([a-z])(")',lambda m:m.group(1)+chr(ord(m.group(2))+1)+m.group(3),out,count=1)
assert c==1
open(p,"w",encoding="utf-8").write(out); print("ok",used)
